mapper.select:
SELECT i.id, i.definition_id, d.flow_name, i.biz_type, i.biz_id, i.biz_no, i.status, (SELECT GROUP_CONCAT(DISTINCT t.node_name) FROM wf_task t WHERE t.instance_id = i.id AND t.status = 'PENDING' AND t.deleted = 0) AS current_node, i.start_user_id, u.nickname AS start_user_name, i.create_time, i.end_time FROM wf_instance i LEFT JOIN wf_definition d ON d.id = i.definition_id AND d.deleted = 0 LEFT JOIN sys_user u ON u.id = i.start_user_id AND u.deleted = 0
i.deleted = 0 AND i.start_user_id = #{startUserId} AND i.biz_no LIKE CONCAT('%', #{keyword}, '%') AND i.biz_type = #{bizType} AND i.status = #{status}
ORDER BY i.id DESC
